(function(){
  function forceRankingPyramid(){
    const out=document.querySelector('#v93ROut');if(!out||out.querySelector('.v124-rank-journey')){out?.querySelector('.v124-rank-journey')?.classList.add('v126-ranking-ready');return}const grid=out.querySelector('.v93-rank-grid');if(!grid)return;
    const original=[...grid.querySelectorAll('.v93-rank-card')];if(original.length<4)return;const first=Number(String(original[0].querySelector('.v93-rank-num')?.textContent||'').replace(/\D/g,'')),cards=first&&first<=3?original.slice(3):original;if(first&&first<=3)original.slice(0,3).forEach(x=>x.remove());out.querySelector('.v121-rank-more')?.remove();
    const journey=document.createElement('section');journey.className='v124-rank-journey v126-ranking-ready';const total=cards.length+3;journey.innerHTML=`<div class="v124-rank-intro"><div><h3>Ruta al podio</h3><p>Las posiciones avanzan por niveles hasta llegar al podio.</p></div><span>${total} supervisoras · clasificación completa</span></div><div class="v124-pyramid"></div>`;const pyramid=journey.querySelector('.v124-pyramid'),tiers=[['Élite','elite',3],['Impulso','impulso',5],['Competencia','competencia',7],['Remontada','remontada',99]];let cursor=0,rank=4;tiers.forEach(([name,tone,size])=>{const slice=cards.slice(cursor,cursor+size);if(!slice.length)return;const end=rank+slice.length-1,tier=document.createElement('section');tier.className='v124-rank-tier';tier.dataset.tone=tone;tier.innerHTML=`<div class="v124-tier-head"><b>${name}</b><span>Posiciones ${rank}–${end}</span></div><div class="v124-tier-grid" style="--tier-cols:${Math.min(slice.length,size===99?7:size)}"></div>`;slice.forEach(c=>tier.lastElementChild.appendChild(c));pyramid.appendChild(tier);cursor+=slice.length;rank=end+1});grid.replaceWith(journey)
  }
  async function refreshHomeControl(){const card=document.querySelector('body.v99-home .v99-module.control'),minis=card?.querySelector('.v99-mini-kpis');if(!card||!minis||card.dataset.v126Operational)return;card.dataset.v126Operational='loading';try{let data=window.__v126Operational;if(!data){const r=await req('/functions/v1/control-auto-resumen-supervisoras',{method:'POST',body:'{}'});if(!r?.data?.ok)throw Error('Resumen no disponible');data=r.data;window.__v126Operational=data}const t=data.totals||{};minis.classList.add('v126-three');minis.innerHTML=`<div class="v99-mini"><span>Unidades activas</span><b>${Number(t.activas||0)}</b></div><div class="v99-mini"><span>Unidades paradas</span><b>${Number(t.paradas||0)}</b></div><div class="v99-mini"><span>Abono adicional</span><b>${Number(t.abono_adicional||0)}</b></div>`;const badge=card.querySelector('.v103-state-copy small');if(badge)badge.textContent=`${Number(t.activas||0)} activas · ${Number(t.paradas||0)} paradas · ${Number(t.abono_adicional||0)} abono adicional`;card.dataset.v126Operational='done'}catch(_){card.dataset.v126Operational='waiting'}}
  async function refreshHomeGps(){const card=document.querySelector('body.v99-home .v99-module.gps'),minis=card?.querySelector('.v99-mini-kpis');if(!card||!minis||card.dataset.v126Gps)return;card.dataset.v126Gps='loading';try{let data=window.__v126HomeGps;if(!data){const r=await req('/functions/v1/gps-rym-admin',{method:'POST',body:JSON.stringify({q:'',galera:'TODAS',estado:'TODOS',onlyProblems:false})});if(!r?.data?.ok)throw Error('Resumen GPS no disponible');data=r.data;window.__v126HomeGps=data}const k=data.kpis||{};minis.classList.add('v126-three');minis.innerHTML=`<div class="v99-mini"><span>Críticas</span><b>${Number(k.criticos||0)}</b></div><div class="v99-mini"><span>Alertas</span><b>${Number(k.alertas||0)}</b></div><div class="v99-mini"><span>Sin GPS</span><b>${Number(k.sin_gps||0)}</b></div>`;card.dataset.v126Gps='done'}catch(_){card.dataset.v126Gps='waiting'}}
  let timer=0;const run=()=>{clearTimeout(timer);timer=setTimeout(()=>{forceRankingPyramid();refreshHomeControl();refreshHomeGps()},150)};new MutationObserver(run).observe(document.documentElement,{subtree:true,childList:true});run();
})();
